import {Game} from './game.js';
import {render,plantImage,bossImage} from './render.js';
import {animateSunCollection} from './art/collection.js';
import {PLANTS,BALANCE as B,CLASSES,METRICS,ZOMBIES} from './data.js';
import {PLANT_LEVELS} from './plantUpgrades.js';
import {UPGRADES,RARITIES,affects} from './roguelikeUpgrades.js';
import {EVOLUTIONS} from './evolutions.js';
import {MAP,TERRAIN,tileCount,screenToWorld} from './map.js';
import {read,write,validate,download,fresh} from './save.js';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d'),modal=$('modal'),images=Object.fromEntries(PLANTS.map(p=>[p.id,plantImage(p.id)]));canvas.width=MAP.cols*MAP.tileSize;canvas.height=MAP.rows*MAP.tileSize;
let meta=read(),selected='peashooter',hover=null,inspected=null,last=performance.now(),acc=0,toastTimer,screen='menu',started=false,inspectionKey='',cardsKey='',pickupsKey='';
const fmt=n=>Number.isFinite(n)?Number(n.toFixed(1)).toLocaleString('pt-BR'):'—',clock=t=>Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');
const iconPaths={play:'M8 5l12 7-12 7z',plants:'M12 21V10M12 14C3 15 3 7 3 4c7 0 10 4 9 10M12 10c0-5 4-7 9-7 0 6-3 10-9 10',upgrades:'M12 21V4M5 11l7-7 7 7',stats:'M5 20V12M12 20V4M19 20V8',save:'M5 3h13l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',settings:'M12 3v3M12 18v3M3 12h3M18 12h3M6 6l2 2M16 16l2 2M6 18l2-2M16 8l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
const icon=k=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+iconPaths[k]+'"/></svg>';
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function persist(){const ok=write(meta);if(!ok)toast('Não foi possível salvar. Exporte o TXT para guardar seu progresso.');return ok}
function show(html,name){screen=name;$('modal-content').innerHTML=html;if(!modal.open)modal.showModal()}
function close(){if(modal.open)modal.close();screen='game';g.paused=false;last=performance.now();acc=0;inspectionKey='';update()}
function title(name){return '<div class="dialog-top"><h2 id="dialog-title">'+name+'</h2><button id="back">Voltar</button></div>'}
function bindBack(fn=menu){$('back').onclick=fn}
function targetName(target){return PLANTS.find(p=>p.id===target)?.name||CLASSES[target?.replace?.('class:','')]||({global:'Todas as plantas',economy:'Economia',base:'Jardim'}[target])||target}
const metricLabels={sunSpawned:'Sun gerado',sunCollected:'Sun coletado',sunMissed:'Sun perdido',sunflowerSun:'Sun de Sunflowers',naturalSun:'Sun natural',plantsPlaced:'Plantas colocadas',plantsLost:'Plantas perdidas',damageDealt:'Dano causado',bossesDefeated:'Bosses derrotados',highestBossWave:'Maior boss wave',sunsAutoCollected:'Suns auto-coletados',sectorsExpanded:'Setores expandidos',evolutionsChosen:'Evolutions escolhidas'};
const g=new Game(meta,onWave,onEnd);
g.events.on('boss:spawn',({boss})=>toast('BOSS WAVE · '+boss.name));g.events.on('boss:defeated',()=>toast('Boss derrotado! +2 Plant Food · +1 Reroll'));g.events.on('sector:unlocked',({sector})=>toast(sector.name+' desbloqueado · nova rota '+sector.spawnEdge));g.events.on('sun:collected',({drop,automatic})=>{animateSunCollection(drop,canvas,$('sun'),automatic)});
function newRun(){g.meta=meta;g.reset();selected='peashooter';inspected=null;started=true;close();toast('Prepare sua defesa. Consulte o plano da próxima wave.')}
function onEnd(){const record=g.wave>meta.highestWave;meta.seeds+=g.earned;meta.highestWave=Math.max(meta.highestWave,g.wave);meta.totalRuns++;meta.kills+=g.kills;meta.time+=Math.floor(g.combatTime);meta.bossStats.totalBossesDefeated+=g.bossesDefeated;meta.bossStats.highestBossWave=Math.max(meta.bossStats.highestBossWave,g.metrics.highestBossWave);for(const k of METRICS)meta.statistics[k]=k==='highestBossWave'?Math.max(meta.statistics[k],Math.floor(g.metrics[k])):meta.statistics[k]+Math.floor(g.metrics[k]);meta.favorites.plant=Object.entries(g.plantUsage).sort((a,b)=>b[1]-a[1])[0]?.[1]>0?Object.entries(g.plantUsage).sort((a,b)=>b[1]-a[1])[0][0]:meta.favorites.plant;meta.favorites.evolution=Object.values(g.selectedEvolutions).at(-1)||meta.favorites.evolution;persist();showGameOver(record)}
function showGameOver(record){show('<small>'+(record?'NOVO RECORDE!':'FIM DA RUN')+'</small><h2 id="dialog-title">Uma nova chance de florescer.</h2><div class="metric-grid">'+[['Wave',g.wave],['Bosses',g.bossesDefeated],['Setores',g.sectorsUnlocked.length],['Zumbis',g.kills],['Sun coletado',g.metrics.sunCollected],['Seeds ganhos','+'+g.earned]].map(([k,v])=>'<div>'+k+'<b>'+v+'</b></div>').join('')+'</div><div class="save-actions"><button id="run-build">Ver build final</button><button class="primary" id="again">Jogar novamente</button><button id="return">Menu</button></div>','over');$('run-build').onclick=()=>buildView(()=>showGameOver(record));$('again').onclick=newRun;$('return').onclick=menu;update()}
function preview(u){if(u.target==='base')return u.id==='foundation'?'HP máximo: '+fmt(g.maxHp)+' → '+fmt(g.maxHp*1.12):'HP: '+fmt(g.hp)+' → '+fmt(Math.min(g.maxHp,g.hp+g.maxHp*.2));if(u.target==='economy')return 'Economia da run';const p=PLANTS.find(p=>affects(u,p));if(!p||!u.effects?.length)return '';const a=g.stats(p),b=g.stats(p,{extra:u}),key=u.effects[0].stat;return targetName(p.id)+': '+fmt(a[key]||0)+' → '+fmt(b[key]||0)}
function onWave(choices,kind='upgrade'){
 if(kind==='evolution'){show('<div class="evolution-title"><small>BOSS DERROTADO · MUTATION REWARD</small><h2 id="dialog-title">Escolha uma Evolution</h2><p>Esta decisão muda o comportamento da espécie e bloqueia os outros caminhos dela nesta run.</p></div><div class="choices evolution-choices">'+choices.map(e=>'<button class="choice evolution-choice" data-evolution="'+e.id+'"><img alt="" src="'+plantImage(e.plant,e.id)+'"><span class="target">'+targetName(e.plant)+'</span><strong>'+e.name+'</strong><p>'+e.description+'</p><span class="before"><b>COMO MUDA:</b> '+e.detail+'</span></button>').join('')+'</div>','evolution');document.querySelectorAll('[data-evolution]').forEach(b=>b.onclick=()=>g.selectEvolution(b.dataset.evolution));return}
 if(kind==='expansion'){show('<small>CAPÍTULO '+(Math.floor(g.wave/10)+1)+'</small><h2 id="dialog-title">Expanda seu jardim</h2><p>Mais espaço para plantar também abre ou reforça uma rota de invasão.</p><div class="choices expansion-choices">'+choices.map(s=>'<button class="choice" data-sector="'+s.id+'"><span class="rarity rare">'+TERRAIN[s.terrain].name+'</span><strong>'+s.name+'</strong><p>+'+tileCount(s)+' tiles plantáveis</p><span class="before">'+TERRAIN[s.terrain].description+'<br><b>ATENÇÃO:</b> rota '+s.spawnEdge.toUpperCase()+'</span></button>').join('')+'</div>','expansion');document.querySelectorAll('[data-sector]').forEach(b=>b.onclick=()=>{if(g.expandSector(b.dataset.sector))close()});return}
 show('<small>WAVE '+g.wave+' CONCLUÍDA · +1 PLANT FOOD</small><h2 id="dialog-title">Escolha como crescer.</h2><p>As primeiras opções favorecem as espécies já usadas. Raros e épicos criam interações.</p><div class="choices">'+choices.map(u=>{const plant=PLANTS.find(p=>affects(u,p));return '<button class="choice" data-upgrade="'+u.id+'"><span class="rarity '+u.rarity+'">'+RARITIES[u.rarity].label+'</span>'+(plant?'<img alt="" src="'+images[plant.id]+'">':'')+'<span class="target">'+targetName(u.target)+'</span><strong>'+u.name+'</strong><p>'+u.desc+'</p><span class="(d-none) before">'+preview(u)+'</span></button>'}).join('')+'</div><button id="reroll" class="reroll" '+(g.rerolls?'':'disabled')+'>REROLL ('+g.rerolls+')</button>','upgrade');document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(g.upgrade(b.dataset.upgrade))close()});$('reroll').onclick=()=>g.rerollUpgrade();
}
function menu(){g.paused=true;show('<div class="main-menu"><div class="menu-art">'+['sunflower','peashooter','wallNut','repeater'].map(id=>'<img alt="" src="'+images[id]+'">').join('')+'</div><h2 id="dialog-title">Garden<span>LAST STAND</span></h2><p>Construa uma defesa. Especialize plantas. Mude o mapa.</p><button class="primary play" id="play">'+icon('play')+' '+(started&&g.state!=='over'?'Continuar run':'Jogar')+'</button><div class="menu-grid"><button id="almanac">'+icon('plants')+'Plantas</button><button id="meta">'+icon('upgrades')+'Melhorias</button><button id="stats">'+icon('stats')+'Estatísticas</button><button id="save-menu">'+icon('save')+'Save</button></div><button id="settings" style="margin-top:15px">'+icon('settings')+' Configurações</button><p><small>Recorde: wave '+meta.highestWave+' · Bosses: '+meta.bossStats.totalBossesDefeated+' · '+meta.seeds+' Seeds</small></p></div>','menu');$('play').onclick=()=>{if(!started||g.state==='over')newRun();else if(['upgrade','evolution','expansion'].includes(g.state))onWave(g.choices,g.state);else close()};$('almanac').onclick=()=>almanac();$('meta').onclick=metaMenu;$('stats').onclick=statistics;$('save-menu').onclick=saveMenu;$('settings').onclick=settings;update()}
function settings(){show(title('Configurações')+'<label class="setting"><span><b>Iniciar waves automaticamente</b><br><small>15s antes da primeira; 9s entre waves.</small></span><input type="checkbox" id="auto" '+(meta.settings.autoStart?'checked':'')+'></label><p>Atalhos: 1–7 plantas, X pá, espaço pausa, Esc cancela. Cooldowns usam tempo da simulação; Suns usam tempo real em 1×/2×/3×.</p>','settings');bindBack();$('auto').onchange=()=>{meta.settings.autoStart=$('auto').checked;g.autoStart=meta.settings.autoStart;persist();update()}}
function saveMenu(){show(title('Seu progresso')+'<p>O schema v3 preserva saves v1/v2 e adiciona Garden Tools e estatísticas de boss. A run ativa não é salva.</p><div class="save-actions"><button id="save">Salvar agora</button><button id="export">Exportar TXT</button><button id="import-btn">Importar TXT</button></div><button class="danger" id="reset">Resetar progresso</button>','save');bindBack();$('save').onclick=()=>persist()&&toast('Progresso salvo.');$('export').onclick=()=>download(meta);$('import-btn').onclick=()=>$('import').click();$('reset').onclick=()=>{show(title('Resetar progresso')+'<p>Todos os Seeds, masteries, Garden Tools e estatísticas serão apagados.</p><button id="confirm-reset" class="danger">Confirmar reset</button>','reset');bindBack(saveMenu);$('confirm-reset').onclick=()=>{meta=fresh();persist();started=false;g.meta=meta;g.reset();menu()}}}
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('Arquivo grande demais.');const incoming=validate(JSON.parse(await f.text()));show(title('Importar progresso')+'<p>Substituir o progresso atual por '+incoming.seeds+' Seeds e recorde '+incoming.highestWave+'?</p><button class="primary" id="confirm-import">Confirmar</button>','import');bindBack(saveMenu);$('confirm-import').onclick=()=>{meta=incoming;persist();g.meta=meta;g.reset();started=false;menu();toast('Save migrado para v3.')}}catch(err){toast('Importação recusada: '+err.message)}finally{e.target.value=''}};
function statistics(){show(title('Estatísticas')+'<div class="metric-grid">'+[['Recorde',meta.highestWave],['Runs',meta.totalRuns],['Bosses',meta.bossStats.totalBossesDefeated],['Maior boss wave',meta.bossStats.highestBossWave],['Planta favorita',targetName(meta.favorites.plant)||'—'],['Evolution favorita',EVOLUTIONS.find(e=>e.id===meta.favorites.evolution)?.name||'—'],['Seeds',meta.seeds],...METRICS.map(k=>[metricLabels[k],meta.statistics[k]])].map(([k,v])=>'<div>'+k+'<b>'+fmtOrText(v)+'</b></div>').join('')+'</div>','statistics');bindBack()}
const fmtOrText=v=>typeof v==='number'?fmt(v):v;
const toolDefs={gloves:{name:'Gardening Gloves',max:2,desc:['+22% no raio de coleta','Coleta Suns muito próximos juntos']},basket:{name:'Sun Basket',max:3,desc:['+3s de duração dos Suns','+6s de duração dos Suns','+9s de duração dos Suns']},magnet:{name:'Sun Magnet',max:3,desc:['Auto-coleta a cada 6s','Auto-coleta a cada 4s','Auto-coleta a cada 2,5s']},reroll:{name:'Seed Satchel',max:3,desc:['Comece com +1 Reroll','Comece com +2 Rerolls','Comece com +3 Rerolls']}};
function metaMenu(){show(title('Melhorias permanentes')+'<p><b>'+meta.seeds+' Seeds</b> · vantagens modestas para a próxima run.</p><h3>Garden Tools</h3>'+Object.entries(toolDefs).map(([k,d])=>metaRow(meta.gardenTools,k,d.name,d.desc[Math.min(meta.gardenTools[k],d.max-1)],d.max)).join('')+'<h3>Mastery</h3>'+PLANTS.map(p=>metaRow(meta.plantMastery,p.id,p.name,masteryText(p),10)).join('')+'<h3>Jardim</h3>'+metaRow(meta,'economy','Starting Sun','+10 Sun inicial por nível',10)+metaRow(meta,'fortress','Base HP','+5% HP por nível',10),'meta');bindBack();document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const [group,key,max]=b.dataset.buy.split(':');buy(group==='meta'?meta:meta[group],key,Number(max))})}
function metaRow(obj,key,name,desc,max){const lv=obj[key],cost=12+lv*10;return '<div class="meta-row"><div><b>'+name+' · '+lv+'/'+max+'</b><small>'+desc+'</small></div><button data-buy="'+(obj===meta?'meta':obj===meta.gardenTools?'gardenTools':'plantMastery')+':'+key+':'+max+'" '+(lv>=max||meta.seeds<cost?'disabled':'')+'>'+(lv>=max?'Máximo':cost+' Seeds')+'</button></div>'}
function buy(obj,key,max){const cost=12+obj[key]*10;if(obj[key]<max&&meta.seeds>=cost){meta.seeds-=cost;obj[key]++;persist();metaMenu()}}
function masteryText(p){const base=p.id==='wallNut'?'+3% HP/nível':p.id==='sunflower'?'+2% Sun/nível':p.id==='potatoMine'?'+3% dano/nível':'+2% dano/nível',milestones={peashooter:'M5: primeira unidade −10% · M10: 5% ervilha extra',repeater:'M5: cooldown −10% · M10: 5% ervilha extra',sunflower:'M5: Suns +2s · M10: primeiro Sun/wave +10',bonkChoy:'M5: ataque +5% · M10: heavy punch antecipado',cabbagePult:'M5: área +10% · M10: primeiro impacto/wave +30% área',potatoMine:'M5: arma 15% antes · M10: primeira explosão/wave +25% dano',wallNut:'M5: cura 5%/wave · M10: primeira unidade +10% HP'};return base+' · '+milestones[p.id]}
function almanac(filter='all'){show(title('Garden Almanac')+'<div class="tabs">'+Object.entries(CLASSES).map(([id,n])=>'<button data-class="'+id+'" class="'+(filter===id?'active':'')+'">'+n+'</button>').join('')+'</div><div class="collection">'+PLANTS.filter(p=>filter==='all'||p.class===filter).map(p=>'<button data-detail="'+p.id+'"><img alt="" src="'+images[p.id]+'"><b>'+p.name+'</b><small>'+CLASSES[p.class]+'</small><strong>'+p.baseCost+' Sun</strong><small>Mastery '+meta.plantMastery[p.id]+'/10</small><p>'+p.role+'</p></button>').join('')+'</div>','almanac');bindBack();document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>almanac(b.dataset.class));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>plantDetail(b.dataset.detail,filter))}
const statNames={hp:'HP máximo',damage:'Dano',attackInterval:'Intervalo de ataque (s)',dps:'DPS médio',range:'Alcance',projectileCount:'Projéteis',splashRadius:'Raio da área',productionInterval:'Produção (s)',sunAmount:'Sun por pickup',armTime:'Tempo para armar',damageReduction:'Redução',regen:'Cura entre waves'};
function plantDetail(id,filter){const p=PLANTS.find(p=>p.id===id),s=g.stats(p,{permanent:true}),base={...p,dps:p.attackInterval?p.damage*(p.projectileCount||1)/p.attackInterval:0},evos=EVOLUTIONS.filter(e=>e.plant===id);show(title(p.name)+'<div class="plant-detail-head"><img alt="'+p.name+'" src="'+images[id]+'"><div><b>'+CLASSES[p.class]+' · Mastery '+meta.plantMastery[id]+'/10</b><p>'+p.role+'</p><small>'+masteryText(p)+'</small></div></div><table class="stat-table"><tbody>'+Object.keys(statNames).filter(k=>s[k]!==undefined&&(s[k]>0||k==='hp')).map(k=>'<tr><td>'+statNames[k]+'</td><td>'+fmt(base[k]||0)+'</td><td>'+fmt(s[k])+'</td></tr>').join('')+'</tbody></table><h3>Possible Evolutions</h3><div class="food-levels">'+evos.map(e=>'<div class="evolution-entry"><img alt="'+e.name+'" src="'+plantImage(e.plant,e.id)+'"><span><b>'+e.name+'</b><br>'+e.description+'</span></div>').join('')+'</div><h3>Plant Food</h3><div class="food-levels"><div><b>LV 1</b> · Forma base</div>'+PLANT_LEVELS[id].map((l,i)=>'<div><b>LV '+(i+2)+'</b> · '+l.desc+'</div>').join('')+'</div><h3>Synergies</h3><p>'+({bonkChoy:'BODYGUARD · combine com Wall-Nut.',sunflower:'GARDEN AURA · sustenta vizinhas.',repeater:'CROSSFIRE · forme pares de Shooters.',peashooter:'CROSSFIRE · forme pares de Shooters.',cabbagePult:'HIGH GROUND · expanda ao leste.',wallNut:'FORTIFIED SOIL · expanda ao sul.',potatoMine:'FERTILE SOIL · primeira planta mais barata.'}[id])+'</p>','detail');bindBack(()=>almanac(filter))}
function buildView(back=close){g.paused=true;const counts={};for(const id of g.upgrades)counts[id]=(counts[id]||0)+1;const evos=Object.values(g.selectedEvolutions).map(id=>EVOLUTIONS.find(e=>e.id===id)),synergyIds=['bodyguard','gardenAura','crossfire'],groups=[['EVOLUTIONS',evos.map(e=>e&&'<div class="build-item"><span class="rarity evolution">Evolution</span><strong>'+e.name+'</strong><p>'+targetName(e.plant)+' · '+e.description+'</p></div>')],['RARE / EPIC',Object.entries(counts).filter(([id])=>UPGRADES.find(u=>u.id===id)?.rarity!=='common'&&!synergyIds.includes(id)).map(([id,n])=>buildItem(id,n))],['POSITIONAL SYNERGIES',Object.entries(counts).filter(([id])=>synergyIds.includes(id)).map(([id,n])=>buildItem(id,n))],['COMMON',Object.entries(counts).filter(([id])=>UPGRADES.find(u=>u.id===id)?.rarity==='common').map(([id,n])=>buildItem(id,n))]];show(title('Sua build')+groups.map(([name,items])=>'<h3>'+name+'</h3>'+(items.filter(Boolean).join('')||'<p>Nenhum.</p>')).join('')+'<h3>PLANT FOOD</h3><p>'+PLANTS.filter(p=>g.levels[p.id]>1).map(p=>p.name+' LV'+g.levels[p.id]).join(' · ')+'</p>','build');bindBack(back)}
function buildItem(id,n){const u=UPGRADES.find(u=>u.id===id);return '<div class="build-item"><span class="rarity '+u.rarity+'">'+RARITIES[u.rarity].label+'</span><strong>'+u.name+' ×'+n+'</strong><p>'+targetName(u.target)+' · '+u.desc+'</p></div>'}

$('plants').innerHTML=PLANTS.map((p,i)=>'<button class="plant-card" data-plant="'+p.id+'"><span class="hotkey">'+(i+1)+'</span><span class="evolvable" hidden>↑ LV</span><span class="cooldown-overlay"></span><img alt="" src="'+images[p.id]+'"><span class="name">'+p.name+'</span><span class="cost"></span><span class="level-pips"></span><span class="field-count"></span></button>').join('');
document.querySelectorAll('[data-plant]').forEach(b=>b.onclick=()=>{selected=b.dataset.plant;inspected=null;inspectionKey='';update()});$('shovel').onclick=()=>{selected=selected==='shovel'?'peashooter':'shovel';inspected=null;update()};
function pointerWorld(e){const r=canvas.getBoundingClientRect();return screenToWorld((e.clientX-r.left)/r.width*canvas.width,(e.clientY-r.top)/r.height*canvas.height,g.camera)}
canvas.addEventListener('pointermove',e=>hover=pointerWorld(e));canvas.addEventListener('pointerleave',()=>hover=null);canvas.addEventListener('contextmenu',e=>{e.preventDefault();selected='shovel';update()});canvas.addEventListener('click',e=>{if(modal.open||g.paused)return;const {x,y}=pointerWorld(e),drop=g.sunDrops.find(s=>Math.hypot(s.x-x,s.y-y)<=B.pickupRadius),result=g.clickMap(x,y,selected);if(result==='sun'){}else if(result?.plant){toast(result.refund?'Planta removida · +'+result.refund+' Sun':'Planta removida · sem refund');inspected=null}else if(typeof result==='object'&&result){inspected=result;selected=null}else if(!result&&selected)toast(selected==='shovel'?'Selecione uma planta para remover.':'Cooldown, Sun insuficiente ou tile indisponível.');inspectionKey='';update()});
$('next').onclick=()=>{g.startWave();update()};$('pause').onclick=()=>{if(!modal.open&&started&&g.state!=='over'){g.paused=!g.paused;last=performance.now();update()}};$('speed').onclick=()=>{g.speed=g.speed%3+1;update()};$('menu').onclick=menu;$('build').onclick=()=>buildView();
document.addEventListener('keydown',e=>{if(modal.open||e.target.matches('input'))return;if(e.code==='Space'){e.preventDefault();$('pause').click()}if(e.key==='Escape'){selected=null;inspected=null}if(e.key.toLowerCase()==='x'){selected='shovel';inspected=null}if(/^[1-7]$/.test(e.key)){selected=PLANTS[Number(e.key)-1].id;inspected=null}inspectionKey='';update()});
modal.addEventListener('cancel',e=>{e.preventDefault();if(['upgrade','evolution','expansion','over','menu'].includes(screen))return;menu()});document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden&&started){g.paused=true;update()}});
function previewHtml(plan){if(!plan)return '';const enemy=plan.enemies.map(e=>'<li><span class="enemy-dot tier-'+ZOMBIES.findIndex(z=>z.id===e.type)+'"></span>'+e.name+' <b>×'+e.count+'</b></li>').join(''),edges=plan.spawnEdges.map(e=>({north:'↑ North',east:'→ East',south:'↓ South',west:'← West'}[e])).join(' · ');return '<small>NEXT WAVE</small><h2>Wave '+plan.waveNumber+(plan.type==='boss'?' · BOSS':'')+'</h2>'+(plan.boss?'<div class="boss-warning"><b>'+plan.boss.name+'</b><span>'+plan.boss.ability+'</span></div>':'')+'<ul>'+enemy+'</ul><p><b>Entradas:</b> '+edges+'<br><b>Threat:</b> '+fmt(plan.threatBudget)+' · '+plan.spawnGroups.length+' grupos</p>'+(plan.waveNumber%B.bossEvery===B.bossEvery-1?'<strong class="next-boss">BOSS NEXT WAVE</strong>':'')}
function update(){
 const enemies=g.zombies.length+g.queue;for(const [id,value] of Object.entries({wave:Math.max(1,g.wave),sun:Math.floor(g.sun),food:g.food,hp:Math.ceil(g.hp)+' / '+Math.ceil(g.maxHp),enemies,kills:g.kills,bosses:g.bossesDefeated,time:clock(g.combatTime),record:meta.highestWave}))$(id).textContent=value;$('health').max=g.maxHp;$('health').value=g.hp;$('pause').textContent=g.paused?'Retomar':'Pausar';$('speed').textContent=g.speed+'×';$('next').disabled=g.state!=='intermission'||g.paused;$('next').textContent=g.state==='intermission'?'Começar wave '+(g.wave+1)+' agora':'Wave '+g.wave+' em andamento';$('countdown').textContent=g.state==='intermission'?(g.autoStart?'Próxima wave em '+Math.ceil(g.countdown)+'s':'Preparação · início manual'):g.state==='playing'?'Proteja o jardim!':'Escolha sua recompensa';
 const plan=g.state==='intermission'?g.nextWavePlan:g.currentWavePlan;$('status').textContent=g.paused?'Pausado':plan?.type==='boss'?'BOSS WAVE '+plan.waveNumber+' · '+plan.boss.name:(plan?.spawnEdges.map(e=>e.toUpperCase()).join(' + ')||'PREPARE-SE')+(g.state==='intermission'?' · preview real':' · colete Sun');$('wave-preview').innerHTML=previewHtml(g.state==='intermission'?g.nextWavePlan:g.currentWavePlan);
 const boss=g.zombies.find(z=>z.bossId);$('boss-hud').hidden=!boss;if(boss){if($('boss-hud').dataset.art!==boss.bossId){$('boss-hud').dataset.art=boss.bossId;$('boss-hud').style.setProperty('--boss-portrait','url("'+bossImage(boss.bossId)+'")')}$('boss-name').textContent=boss.name;$('boss-phase').textContent=boss.chargeState==='telegraph'?'PREPARANDO CHARGE':boss.chargeState==='charging'?'CHARGING':boss.ability;$('boss-health').max=boss.maxHp;$('boss-health').value=boss.hp;$('boss-percent').textContent=Math.ceil(boss.hp/boss.maxHp*100)+'%'}
 const ck=[Math.floor(g.sun),g.food,selected,g.plantRevision,g.upgrades.length,...Object.values(g.cooldowns).map(x=>x.toFixed(1)),...PLANTS.map(p=>g.fieldCount(p.id))].join('|');if(ck!==cardsKey){cardsKey=ck;$('shovel').classList.toggle('selected',selected==='shovel');document.querySelectorAll('[data-plant]').forEach(b=>{const p=PLANTS.find(p=>p.id===b.dataset.plant),s=g.stats(p),n=g.fieldCount(p.id),cost=g.getPlantCost(p.id),cool=g.cooldowns[p.id],c=b.querySelector('.cost');b.dataset.lastCost=cost;b.classList.toggle('selected',selected===p.id);b.setAttribute('aria-disabled',String(g.sun<cost||cool>0));c.textContent=cost+' Sun';b.querySelector('.field-count').textContent=n?'×'+n:'';b.querySelector('.evolvable').hidden=g.food<g.foodCost(p.id);b.querySelector('.level-pips').textContent='LV'+g.levels[p.id]+' '+Array.from({length:5},(_,i)=>i<g.levels[p.id]?'●':'○').join('');const overlay=b.querySelector('.cooldown-overlay');overlay.style.height=(cool/(s.cooldown||1)*100)+'%';overlay.textContent=cool>0?cool.toFixed(1)+'s':'';b.title=p.name+' · '+CLASSES[p.class]+'\n'+p.role+'\nCooldown: '+p.cooldown+'s\nPróxima: '+cost+' Sun'})}
 const pk=g.sunDrops.map(s=>s.id+':'+s.amount).join(',');if(pk!==pickupsKey){pickupsKey=pk;$('pickup-controls').innerHTML=g.sunDrops.map(s=>'<button class="pickup-button" data-sun="'+s.id+'" aria-label="Coletar '+s.amount+' Sun" style="left:'+s.x/MAP.cols*100+'%;top:'+s.y/MAP.rows*100+'%"></button>').join('');document.querySelectorAll('[data-sun]').forEach(b=>b.onclick=()=>{const s=g.collectSun(Number(b.dataset.sun));update()})}
 const p=inspected&&g.plants.includes(inspected)?inspected:PLANTS.find(p=>p.id===selected),key=[p?.id,p?.uid,g.levels[p?.id],g.upgrades.length,g.food,g.plantRevision,g.paused].join('|');if(key!==inspectionKey){inspectionKey=key;if(!p)$('inspect').innerHTML='<h2>'+(selected==='shovel'?'Pá selecionada':'Seu jardim, sua estratégia.')+'</h2><p>'+(selected==='shovel'?'Clique numa planta. Na preparação, recupera 25% do preço pago; durante a wave, não há refund.':'Selecione uma planta para ver atributos.')+'</p>';else{const s=g.stats(p),lv=g.levels[p.id],cost=g.foodCost(p.id),evo=EVOLUTIONS.find(e=>e.id===g.selectedEvolutions[p.id]);$('inspect').innerHTML='<div class="inspect-head"><img alt="" src="'+images[p.id]+'"><h2>'+p.name+'<small>'+CLASSES[p.class]+' · LV '+lv+'</small></h2></div>'+(evo?'<p class="evolution-chip">'+evo.name+'</p>':'')+'<p><b>'+p.abilityName+'</b> · '+p.description+'</p><div class="compact-stats"><span>HP<b id="plant-hp"></b></span>'+(s.damage?'<span>Dano / DPS<b>'+fmt(s.damage)+' / '+fmt(s.dps)+'</b></span><span>Intervalo<b>'+fmt(s.attackInterval||0)+'s</b></span><span>Alcance<b>'+fmt(s.range)+'</b></span>':s.productionInterval?'<span>Sun<b>'+fmt(s.sunAmount)+'</b></span><span>Produção<b>'+fmt(s.productionInterval)+'s</b></span>':'<span>Redução / cura<b>'+fmt(s.damageReduction*100)+'% / '+fmt(s.regen*100)+'%</b></span>')+'</div><div class="evolve-detail"><strong>'+(lv<5?'LV '+lv+' → LV '+(lv+1):'Nível máximo')+'</strong><p>'+(PLANT_LEVELS[p.id][lv-1]?.desc||'Todos os níveis desbloqueados.')+'</p><button id="feed" '+(g.food<cost||g.paused||lv>=5?'disabled':'')+'>'+(lv>=5?'LV 5 / 5':'Evoluir · '+cost+' Plant Food')+'</button></div>';$('feed').onclick=()=>{if(g.plantFood(p.id)){inspectionKey='';toast('Plant Food aplicado.');update()}}}}
 if(inspected&&g.plants.includes(inspected)&&inspected.id==='potatoMine'&&EVOLUTIONS.find(e=>e.id===g.selectedEvolutions.potatoMine)?.remote&&inspected.age>=g.stats(inspected).armTime&&!$('detonate')){const b=document.createElement('button');b.id='detonate';b.className='danger';b.textContent='DETONAR AGORA';b.onclick=()=>{g.explodeMine(inspected);g.cleanupPlants();inspected=null;inspectionKey='';update()};$('inspect').append(b)}if(p&&$('plant-hp'))$('plant-hp').textContent=inspected&&g.plants.includes(inspected)?fmt(inspected.hp)+' / '+fmt(inspected.maxHp):fmt(g.stats(p).hp);$('upgrades').innerHTML=Object.values(g.selectedEvolutions).slice(-1).map(id=>'<div class="upgrade-line"><span class="rarity evolution">EVOLUTION</span>'+EVOLUTIONS.find(e=>e.id===id).name+'</div>').join('')+g.upgrades.slice(-3).reverse().map(id=>{const u=UPGRADES.find(u=>u.id===id);return '<div class="upgrade-line"><span class="rarity '+u.rarity+'">'+RARITIES[u.rarity].label+'</span>'+u.name+'</div>'}).join('')||'<p>Complete waves e escolha sua build.</p>';
}
if(B.debug||location.search.includes('debug=1')){const panel=document.createElement('div');panel.className='debug';document.querySelector('aside').append(panel);const actions={'Spawn Boss':()=>{g.wave=9;g.nextWavePlan=null;g.startWave()},'Wave 10':()=>{g.wave=9;g.nextWavePlan=null;g.startWave()},'Wave 20':()=>{g.wave=19;g.nextWavePlan=null;g.startWave()},'+Reroll':()=>g.rerolls++,'Unlock Sector':()=>{g.state='expansion';g.expandSector(['east','south','west','north'].find(x=>!g.map.activeSectors.has(x)))},'Give Evolution':()=>{g.state='evolution';g.choices=EVOLUTIONS.slice(0,3);g.selectEvolution(g.choices[0])},'Spawn Sun':()=>g.spawnSun('natural',4,4,25),'+Food':()=>g.food+=5,'Reset Wave':()=>{g.zombies=[];g.spawnQueue=[];g.queue=0;g.finishWave()}};for(const [name,fn] of Object.entries(actions)){const b=document.createElement('button');b.textContent=name;b.onclick=()=>{fn();update()};panel.append(b)}}
let tick=0,lastRevision=-1;function loop(now){const dt=Math.min((now-last)/1000,.1);last=now;acc+=dt*g.speed;while(acc>=1/60){g.step(1/60);acc-=1/60}render(ctx,g,selected,hover,inspected,dt);tick+=dt;if(tick>.1||g.plantRevision!==lastRevision||pickupsKey!==g.sunDrops.map(s=>s.id+':'+s.amount).join(',')){lastRevision=g.plantRevision;tick=0;update()}requestAnimationFrame(loop)}
update();menu();requestAnimationFrame(loop);
